const DETAILED_SOLUTIONS={"practice": {"1": [{"title": "Отрицание внешнего квантора", "text": "Запись утверждает: для каждого x можно подобрать свой y с истинным P(x,y). Чтобы это опровергнуть, достаточно одного неподходящего x."}, {"title": "Фиксация нарушителя", "text": "Меняем внешний ∀x на ∃x. Для выбранного x никакой y не должен спасать исходное утверждение."}, {"title": "Отрицание внутреннего квантора", "text": "Отрицание «существует y с P» есть «для любого y выполнено ¬P». Меняем ∃y на ∀y, сохраняя порядок x,y."}, {"title": "Сборка формулы", "text": "Получаем ∃x∀y:¬P(x,y). Отрицание относится к P, а не только к одному из кванторов."}, {"title": "Проверка слов", "text": "«Найдётся x, для которого при каждом y свойство P ложно» действительно исключает возможность подобрать подходящий y для каждого x."}], "2": [{"title": "Чтение интервала", "text": "X=[−2,+∞) содержит −2 и все большие действительные числа. Правый символ ∞ не обозначает элемент множества."}, {"title": "Проверка нижних граней", "text": "Если m≤−2, то для каждого x∈X имеем m≤−2≤x. Поэтому каждое такое m является нижней гранью."}, {"title": "Исключение остальных чисел", "text": "Если m>−2, элемент x=−2 нарушает условие m≤x. Следовательно, других нижних граней нет."}, {"title": "Отсутствие верхней грани", "text": "Для любого предложенного M возьмём x=max(−2,M+1). Тогда x∈X и x>M, так что M не является верхней гранью."}, {"title": "Вывод", "text": "Все нижние грани образуют (−∞,−2]; верхних вещественных граней нет. Дополнительно inf X=min X=−2."}], "3": [{"title": "Оценка всех элементов", "text": "При n≥1 выполняется 0≤1−1/n<1. Значит, 0 является нижней, а 1 — верхней гранью."}, {"title": "Достижение нижней грани", "text": "Для n=1 получаем 1−1=0. Нижняя грань принадлежит X, поэтому inf X=min X=0."}, {"title": "Точность верхней грани", "text": "Возьмём любое ε>0 и натуральное n>1/ε. Тогда 1/n<ε и 1−ε<1−1/n<1."}, {"title": "Смысл ε-оценки", "text": "Элементы X подходят к 1 снизу ближе любого положительного расстояния. Поэтому уменьшить верхнюю грань 1 нельзя: sup X=1."}, {"title": "Отсутствие максимума", "text": "Равенство 1−1/n=1 потребовало бы 1/n=0, чего нет при конечном n. Более того, следующий член больше предыдущего."}], "4": [{"title": "Определение суммы множеств", "text": "Элемент X+Y имеет вид x+y, где 0<x<2 и −1≤y≤3. Складываются все допустимые пары, а не только края."}, {"title": "Верхняя оценка", "text": "Из x<2 и y≤3 следует x+y<5. Таким образом, 5 — верхняя грань суммы."}, {"title": "Приближение к границе", "text": "Для произвольного ε>0 положим h=min(ε/2,1), x=2−h и y=3. Эти элементы допустимы, а их сумма равна 5−h>5−ε."}, {"title": "Точность", "text": "Найдена сумма выше 5−ε для каждого ε>0. Вместе с верхней оценкой это доказывает sup((0,2)+[−1,3])=5."}, {"title": "Проверка достижения", "text": "Значение 5 не достигается, поскольку x никогда не равен 2. Отсутствие максимума не мешает супремуму равняться 5."}], "5": [{"title": "Определение верхней грани", "text": "A — верхняя грань X, если каждый x∈X удовлетворяет x≤A."}, {"title": "Пустая область проверки", "text": "При X=∅ нарушающего элемента нет. Поэтому условие выполняется для любого A∈ℝ: все вещественные числа являются верхними гранями."}, {"title": "Что требуется от sup", "text": "Супремум должен быть наименьшим из всех этих верхних граней."}, {"title": "Почему наименьшего нет", "text": "Для любого кандидата A число A−1 тоже является верхней гранью и меньше A. Ни один кандидат не может быть наименьшим."}, {"title": "Уточнение области чисел", "text": "Поэтому у ∅ нет вещественного супремума. В расширенной числовой прямой иногда вводят sup ∅=−∞ по отдельному соглашению; это другое утверждение."}], "6": [{"title": "Построение контрпримера", "text": "Зададим x₂ₖ=0, x₂ₖ₋₁=k. Нули встречаются бесконечно часто, а нечётные члены уходят вверх."}, {"title": "Предельная точка 0", "text": "Подпоследовательность x₂ₖ постоянно равна 0, значит сходится к 0. Поэтому 0 — конечная предельная точка."}, {"title": "Почему других конечных точек нет", "text": "У любой сходящейся подпоследовательности не может быть бесконечно много нечётных членов: их значения k неограниченно растут. Она должна с некоторого места состоять из нулей."}, {"title": "Отсутствие сходимости", "text": "Если бы вся последовательность сходилась, её чётная подпоследовательность заставила бы предел равняться 0. Но нечётные значения k не попадают в окрестность (−1,1) при больших k."}, {"title": "Роль ограниченности", "text": "Для ограниченной последовательности с единственной предельной точкой сходимость верна: иначе из членов вне фиксированной окрестности выделилась бы вторая предельная точка по Больцано–Вейерштрассу."}], "7": [{"title": "Разбиение индексов", "text": "При n=2k значение (−1)ⁿ=1, а при n=2k−1 оно равно −1."}, {"title": "Ограниченность", "text": "Для каждого n модуль члена равен 1. Поэтому последовательность ограничена числом 1."}, {"title": "Пределы подпоследовательностей", "text": "Чётные члены сходятся к 1, нечётные — к −1, поскольку обе подпоследовательности постоянны."}, {"title": "Противоречие с общей сходимостью", "text": "У сходящейся последовательности все подпоследовательности имеют тот же предел. Два разных значения 1 и −1 исключают общий предел."}, {"title": "Проверка остальных вариантов", "text": "Последовательности 1/n и 2+1/n сходятся соответственно к 0 и 2. Значит, требованию «ограничена, но не сходится» отвечает только (−1)ⁿ."}], "8": [{"title": "Выбор точности", "text": "Из xₙ→−3 можно использовать любую положительную точность. Возьмём ε=3/2."}, {"title": "Запись определения", "text": "Существует N, после которого |xₙ−(−3)|=|xₙ+3|<3/2 для каждого n>N."}, {"title": "Раскрытие модуля", "text": "Получаем −3/2<xₙ+3<3/2. Вычитаем 3 из всех частей: −9/2<xₙ<−3/2."}, {"title": "Нужный вывод", "text": "Все достаточно поздние члены строго меньше −1,5. Это утверждение именно о хвосте, а не о первых членах."}, {"title": "Проверка сильных вариантов", "text": "Можно задать x₁=100, а затем xₙ=−3+1/n. Предел всё равно −3, но первый член положителен и поздние члены не обязаны точно равняться пределу."}], "9": [{"title": "Переход к нестрогим оценкам", "text": "Неравенство 0<xₙ<1 в частности даёт 0≤xₙ≤1."}, {"title": "Пределы границ", "text": "Постоянные последовательности 0 и 1 имеют пределы 0 и 1."}, {"title": "Применение теоремы", "text": "При переходе к пределу сохраняются нестрогие неравенства. Поэтому 0≤a≤1."}, {"title": "Проверка левого края", "text": "Последовательность xₙ=1/(n+1) удовлетворяет исходным строгим оценкам, но сходится к 0."}, {"title": "Проверка правого края", "text": "Последовательность xₙ=1−1/(n+1) также удовлетворяет условию и сходится к 1. Следовательно, строгие оценки на предел утверждать нельзя."}], "10": [{"title": "Оценка числителя", "text": "Для любого действительного аргумента −1≤sin n≤1. Предел самого sin n искать не требуется."}, {"title": "Деление на положительное число", "text": "При натуральном n>0 деление сохраняет порядок: −1/n≤sin n/n≤1/n."}, {"title": "Пределы границ", "text": "Обе крайние последовательности стремятся к 0."}, {"title": "Применение зажатия", "text": "По лемме о двух милиционерах промежуточная последовательность sin n/n также стремится к 0."}, {"title": "Проверка по определению", "text": "Для ε>0 достаточно n>1/ε: тогда |sin n/n|≤1/n<ε. Это независимое подтверждение ответа 0."}], "11": [{"title": "Проверка неограниченности", "text": "Нечётные члены x₂ₖ₋₁=k превышают любой заданный положительный порог при достаточно большом k."}, {"title": "Определение бесконечной большой", "text": "Требовалось бы, чтобы после некоторого N все члены удовлетворяли |xₙ|>M для каждого M>0."}, {"title": "Фиксация порога", "text": "Уже для M=1 это невозможно: как бы далеко ни выбрать N, найдётся чётный индекс 2k>N."}, {"title": "Нарушающий член", "text": "У этого индекса |x₂ₖ|=0≤1. Следовательно, условие на весь хвост не выполнено."}, {"title": "Вывод и обратная величина", "text": "Последовательность неограниченна, но не бесконечно большая. Величина 1/xₙ к тому же не определена на чётных индексах."}], "12": [{"title": "Назвать новую последовательность", "text": "Положим βₙ=|αₙ|. Нужно доказать βₙ→0, то есть малость её расстояния до нуля."}, {"title": "Упростить расстояние до нуля", "text": "Модуль уже неотрицателен, поэтому |βₙ−0|=||αₙ||=|αₙ|."}, {"title": "Выбрать номер", "text": "Для произвольной ε>0 исходная сходимость αₙ→0 даёт n₀ с |αₙ|<ε при каждом n>n₀."}, {"title": "Проверить весь хвост", "text": "Для тех же n имеем |βₙ−0|=|αₙ|<ε. Определение сходимости βₙ к нулю выполнено без нового выбора номера."}, {"title": "Проверить неверные варианты", "text": "Например, αₙ=(−1)ⁿ/n стремится к нулю, а |αₙ|=1/n никогда не равно нулю при конечном n. При этом предел модуля всё равно существует и равен 0."}], "13": [{"title": "Проверка знаменателя", "text": "При натуральных n≥1 величина 2n−1 положительна, поэтому исходная дробь определена."}, {"title": "Нормировка", "text": "Делим числитель и знаменатель на n: (3n+2)/(2n−1)=(3+2/n)/(2−1/n)."}, {"title": "Пределы частей", "text": "Дроби 2/n и 1/n стремятся к 0. Поэтому числитель стремится к 3, знаменатель — к 2."}, {"title": "Правило частного", "text": "Предел знаменателя 2 не равен нулю. Значит, предел отношения равен 3/2."}, {"title": "Проверка ошибки", "text": "Коэффициенты берутся в порядке «числитель / знаменатель». Ответ 2/3 получился бы при переворачивании исходной дроби."}], "14": [{"title": "Монотонность", "text": "Разность соседних членов равна (2−1/(n+1))−(2−1/n)=1/[n(n+1)]>0."}, {"title": "Верхняя грань", "text": "Каждый член меньше 2, поскольку 1/n>0. Последовательность возрастает и ограничена сверху."}, {"title": "Существование предела", "text": "Теорема о монотонной ограниченной последовательности гарантирует конечный предел."}, {"title": "Определение значения", "text": "Для ε>0 выбираем N>1/ε. При n>N имеем |(2−1/n)−2|=1/n<ε."}, {"title": "Вывод", "text": "Предел равен 2. Монотонность объясняет направление приближения, а ε-оценка доказывает именно это значение."}], "15": [{"title": "Бином Ньютона", "text": "В разложении (x+1)⁵ общий член имеет вид C₅ᵏxᵏ·1⁵⁻ᵏ при k=0,…,5."}, {"title": "Выбор степени", "text": "Для получения x² необходимо выбрать k=2. Никакой другой член такой степени не содержит."}, {"title": "Формула сочетаний", "text": "C₅²=5!/(2!·3!). Сокращаем 3!: остаётся (5·4)/(2·1)."}, {"title": "Вычисление", "text": "Получаем 20/2=10, поэтому нужный член равен 10x²."}, {"title": "Смысл коэффициента", "text": "Из пяти множителей выбираются ровно два, в которых берём x; в трёх остальных берём 1. Число таких неупорядоченных выборов равно 10."}], "16": [{"title": "Проверка вложенности", "text": "Если 0<x<1/(n+1), то также 0<x<1/n. Интервалы действительно вложены."}, {"title": "Кандидат в общей части", "text": "Допустим, существует x, принадлежащий всем (0,1/n). Тогда x>0."}, {"title": "Выбор нарушающего номера", "text": "По архимедову свойству найдётся натуральное n>1/x. Отсюда 1/n<x."}, {"title": "Противоречие", "text": "Принадлежность n-му интервалу требовала x<1/n, а мы получили обратное. Положительного общего элемента нет; 0 исключён из каждого интервала."}, {"title": "Сопоставление с теоремой", "text": "Длины стремятся к нулю и вложенность есть, но интервалы не замкнуты. Для отрезков [0,1/n] общей точкой был бы 0."}], "17": [{"title": "Ограниченность", "text": "Для всех n выполняется |sin n|≤1. Это проверяет основную гипотезу теоремы Больцано–Вейерштрасса."}, {"title": "Применение теоремы", "text": "Из любой ограниченной вещественной последовательности можно выделить сходящуюся подпоследовательность sin nₖ."}, {"title": "Положение предела", "text": "Все её члены лежат в [−1,1], поэтому предел также принадлежит этому отрезку по переходу к неравенствам."}, {"title": "Граница утверждения", "text": "Теорема гарантирует существование хотя бы одной подходящей последовательности индексов nₖ, но не утверждает сходимость всех членов sin n."}, {"title": "Проверка вариантов", "text": "Монотонность исходной последовательности также не следует из её ограниченности. Верным является только утверждение о подпоследовательности."}], "18": [{"title": "Запись критерия Коши", "text": "Для сходимости Hₙ требовалось бы: при любой ε>0 все достаточно поздние Hₘ и Hₙ отличаются менее чем на ε."}, {"title": "Выбор точности", "text": "Фиксируем ε₀=1/2. Она не зависит от того, насколько далеко предложат уйти по номерам."}, {"title": "Выбор индексов", "text": "Для любого N берём n>N и m=2n. Оба индекса находятся после N."}, {"title": "Оценка хвоста", "text": "H₂ₙ−Hₙ=1/(n+1)+…+1/(2n). Здесь n слагаемых, каждое не меньше 1/(2n), поэтому сумма не меньше 1/2."}, {"title": "Отрицание критерия", "text": "Получили |H₂ₙ−Hₙ|≥ε₀ при сколь угодно поздних индексах. Следовательно, конечного предела нет. Убывание отдельных слагаемых 1/n к нулю этого вывода не меняет."}], "19": [{"title": "Цель контрпримера", "text": "По Гейне общий предел заставил бы значения функции иметь одинаковый предел вдоль любой допустимой последовательности аргументов к 0."}, {"title": "Первая последовательность", "text": "Возьмём xₙ=1/(π/2+2πn). Она положительна, не равна нулю и стремится к 0."}, {"title": "Первый предел значений", "text": "По периодичности sin(1/xₙ)=sin(π/2+2πn)=1 для каждого n."}, {"title": "Вторая последовательность", "text": "Возьмём yₙ=1/(3π/2+2πn). Она также стремится к 0, но sin(1/yₙ)=−1."}, {"title": "Противоречие", "text": "Пределы значений 1 и −1 различны, значит общего предела sin(1/x) при x→0 нет. Пара одинаковых аргументов такого противоречия не дала бы."}], "20": [{"title": "Выбор точности", "text": "Из f(x)→5 используем ε=5/2. Определение действует в достаточно малой проколотой окрестности предельной точки a."}, {"title": "Раскрытие определения", "text": "Для всех допустимых x при 0<|x−a|<δ имеем |f(x)−5|<5/2."}, {"title": "Раскрытие модуля", "text": "Получаем −5/2<f(x)−5<5/2, откуда 5/2<f(x)<15/2."}, {"title": "Нужное утверждение", "text": "В частности, f(x)>2,5 на этой проколотой окрестности."}, {"title": "Почему значение в точке не известно", "text": "Предел не фиксирует f(a). Например, можно положить f(x)=5+x при x≠a=0 и f(0)=100. Предел всё равно равен 5; равенства f(x)=5 также не требуется."}], "21": [{"title": "Непрерывность частей", "text": "Многочлены x²+1 и x+1 непрерывны в точке 2."}, {"title": "Проверка знаменателя", "text": "При x=2 знаменатель равен 3≠0. В некоторой окрестности 2 он остаётся ненулевым, поэтому частное непрерывно."}, {"title": "Подстановка в числитель", "text": "2²+1=4+1=5."}, {"title": "Подстановка в знаменатель", "text": "2+1=3. Применяем правило частного: искомый предел равен 5/3."}, {"title": "Проверка порядка", "text": "Ответ 3/5 относится к обратной дроби. Никакой неопределённости 0/0 в этой задаче нет."}], "22": [{"title": "Проблема в точке", "text": "При x=0 запись sin x/x не определена. Назначение значения в нуле называется доопределением."}, {"title": "Условие непрерывности", "text": "Для непрерывности нужно выбрать f(0), совпадающее с пределом исходного отношения при x→0."}, {"title": "Вычисление предела", "text": "По первому замечательному пределу lim sin x/x=1, если аргумент измеряется в радианах."}, {"title": "Выбор значения", "text": "Полагаем f(0)=1. Тогда предел равен значению функции, то есть выполнено определение непрерывности."}, {"title": "Единственность выбора", "text": "Значение 0 или π не совпадало бы с пределом 1. Разрыв при таком выборе остался бы устранимым."}], "23": [{"title": "Выделение функций", "text": "Внутренняя функция g(x)=x² определена и непрерывна на всей ℝ. Внешняя функция h(t)=sin t также непрерывна на всей ℝ."}, {"title": "Проверка области композиции", "text": "Значения x² неотрицательны, но синус определён для любых вещественных t. Ограничений на x не возникает."}, {"title": "Предел внутренней функции", "text": "В произвольной точке a имеем x²→a² при x→a."}, {"title": "Непрерывность внешней функции", "text": "Поэтому sin(x²)→sin(a²), что равно значению композиции в точке a."}, {"title": "Вывод", "text": "Так как a была произвольна, sin(x²) непрерывна на всей ℝ, включая нуль и отрицательные аргументы."}], "24": [{"title": "Найти область определения", "text": "Знаменатель x−2 не должен равняться нулю, поэтому x≠2."}, {"title": "Проверить непрерывность частей", "text": "Постоянный числитель 1 и линейная функция x−2 непрерывны в каждой вещественной точке."}, {"title": "Применить правило частного", "text": "В любой точке a≠2 значение a−2 ненулевое. Поэтому частное непрерывно в a."}, {"title": "Исключить запрещённую точку", "text": "При a=2 функция не определена; включать эту точку в область непрерывности нельзя."}, {"title": "Сравнить варианты", "text": "Отрицательные и любые другие x<2 тоже допустимы: например, при x=1 знаменатель −1. Поэтому правильная область — ℝ без точки 2, а не только правая полуось."}], "25": [{"title": "Проверка формы", "text": "При x→0 и числитель, и знаменатель стремятся к нулю. Прямая подстановка не вычисляет отношение."}, {"title": "Выделение стандартных отношений", "text": "Для малых x≠0 перепишем sin(5x)/tg(2x) как [sin(5x)/(5x)]·[(2x)/tg(2x)]·(5/2)."}, {"title": "Первый множитель", "text": "Из 5x→0 и первого замечательного предела получаем sin(5x)/(5x)→1."}, {"title": "Второй множитель", "text": "Переписываем v/tg v=(v/sin v)·cos v. Первый множитель стремится к 1 по первому замечательному пределу, второй — к 1 по непрерывности косинуса. Поэтому v/tg v→1."}, {"title": "Перемножение пределов", "text": "Получаем 1·1·5/2=5/2. Постоянная 5/2 сохраняет различие аргументов, её нельзя потерять или перевернуть."}], "26": [{"title": "Проверка основания", "text": "Для достаточно малых |x|<1/6 имеем 1+3x>1/2>0. Вещественная степень определена по обе стороны от нуля."}, {"title": "Замена переменной", "text": "Положим t=3x. Тогда t→0 и 2/x=6/t."}, {"title": "Точное преобразование", "text": "(1+3x)^(2/x)=(1+t)^(6/t)=[(1+t)^(1/t)]⁶ при t≠0."}, {"title": "Применение второго предела", "text": "Выражение в квадратных скобках стремится к e."}, {"title": "Вывод", "text": "Непрерывность шестой степени даёт предел e⁶. Показатель 6 получается произведением коэффициента 3 в основании и коэффициента 2 в степени."}], "27": [{"title": "Значения функции", "text": "Функция Дирихле принимает 1 на рациональных аргументах и 0 на иррациональных."}, {"title": "Плотность двух множеств", "text": "В любой проколотой окрестности точки a можно выбрать рациональный x и иррациональный y."}, {"title": "Фиксация точности", "text": "Возьмём ε₀=1/2 независимо от радиуса δ окрестности."}, {"title": "Нарушение оценки", "text": "У выбранных аргументов |D(x)−D(y)|=|1−0|=1≥1/2. Поэтому требование критерия Коши «разность меньше ε₀» не выполняется ни при каком δ."}, {"title": "Проверка других порогов", "text": "При ε₀=2 или 3 все разности значений были бы меньше порога. Эти числа не дают нужного опровержения."}], "28": [{"title": "Выделение старшей степени", "text": "При x→+∞ число x² положительно и не равно нулю. Делим на него обе части дроби."}, {"title": "Преобразование", "text": "(2x²+1)/(x²−3)=(2+1/x²)/(1−3/x²)."}, {"title": "Малые слагаемые", "text": "При x→+∞ имеем 1/x²→0 и 3/x²→0."}, {"title": "Проверка частного", "text": "Предел знаменателя равен 1, а не 0. При достаточно больших x исходный знаменатель также ненулевой."}, {"title": "Ответ", "text": "По арифметике пределов отношение стремится к 2/1=2. Равные степени числителя и знаменателя дают конечное отношение старших коэффициентов."}], "29": [{"title": "Точная тригонометрическая формула", "text": "Используем 1−cos(3x)=2sin²(3x/2). Это равенство, а не замена близких разностей без обоснования."}, {"title": "Нормировка аргумента", "text": "Обозначим t=3x/2. Тогда x²=(4/9)t²."}, {"title": "Преобразование дроби", "text": "(1−cos 3x)/x²=(9/2)·(sin t/t)² для x≠0."}, {"title": "Вычисление предела", "text": "По первому замечательному пределу sin t/t→1, поэтому результат равен (9/2)·1²=9/2."}, {"title": "Проверка коэффициента", "text": "Эквивалентность 1−cos u∼u²/2 при u=3x тоже даёт 9x²/2. Коэффициент аргумента нужно возвести в квадрат."}], "30": [{"title": "Содержание теоремы", "text": "Непрерывная функция ограничена на замкнутом ограниченном отрезке [a,b]. Все условия относятся к области, на которой рассматривают функцию."}, {"title": "Проверка области", "text": "Множество (0,1] ограничено, но не замкнуто: последовательность 1/n лежит в нём и стремится к отсутствующей точке 0."}, {"title": "Проверка функции", "text": "Функция 1/x непрерывна в каждой точке своей области (0,1], в том числе в 1 относительно области."}, {"title": "Фактическая неограниченность", "text": "На аргументах x=1/n значения равны n и не имеют общей верхней грани."}, {"title": "Вывод", "text": "Противоречия теореме нет, потому что условие замкнутого отрезка не выполнено. Нельзя заменить его одной ограниченностью области."}], "31": [{"title": "Нижняя оценка", "text": "Квадрат любого действительного числа неотрицателен, значит x²≥0 на [−2,1]."}, {"title": "Достижение минимума", "text": "Точка 0 входит в отрезок и даёт 0²=0. Поэтому min=0, а не только inf=0."}, {"title": "Верхняя оценка", "text": "Для −2≤x≤1 модуль x не больше 2. Следовательно, x²≤4."}, {"title": "Достижение максимума", "text": "В точке x=−2 получаем x²=4. Значит, max=4."}, {"title": "Проверка обоих концов", "text": "В правом конце 1²=1, но это меньше 4. Проверка только правого конца ошибочно дала бы неверный максимум."}], "32": [{"title": "Выбор функции", "text": "Положим f(x)=x³+x−1. Это многочлен, поэтому он непрерывен на всём [0,1]."}, {"title": "Знаки на концах", "text": "f(0)=−1<0, f(1)=1>0. Их произведение отрицательно."}, {"title": "Применение теоремы", "text": "По теореме о переходе через нуль существует c∈(0,1) с f(c)=0. Концы не подходят, так как их значения ненулевые."}, {"title": "Уточнение единственности", "text": "Если 0≤x<y≤1, то f(y)−f(x)=(y−x)(y²+xy+x²+1)>0. Функция строго возрастает, поэтому двух корней быть не может."}, {"title": "Ответ на вопрос", "text": "Корень есть; дополнительно он единственный. Для ответа «есть» достаточно непрерывности и разных знаков, находить точное значение корня не требуется."}], "33": [{"title": "Смысл отрезка", "text": "Рассматриваем непрерывную функцию на [0,1] с известными концевыми значениями −2 и 5."}, {"title": "Положение нужного уровня", "text": "Число 3 лежит строго между −2 и 5."}, {"title": "Сведение к нулю", "text": "Введём g(x)=f(x)−3. Она непрерывна, g(0)=−5<0, g(1)=2>0."}, {"title": "Применение теоремы", "text": "Существует c∈(0,1), для которого g(c)=0. Возвращаясь к f, получаем f(c)=3."}, {"title": "Проверка роли монотонности", "text": "Существование получено без монотонности. Точек уровня 3 может быть несколько; это не противоречит условию."}], "34": [{"title": "Ограничение исходной области", "text": "На x≥0 функция x² строго возрастает: при 0≤x<y имеем y²−x²=(y−x)(y+x)>0."}, {"title": "Непрерывность", "text": "Квадрат — многочлен, поэтому непрерывен на [0,+∞)."}, {"title": "Образ", "text": "Значения x² неотрицательны; каждое y≥0 достигается при x=√y. Поэтому образ точно равен [0,+∞)."}, {"title": "Построение обратной", "text": "Из y=x² и условия x≥0 однозначно получаем x=√y. Проверки: (√y)²=y и √(x²)=x на x≥0."}, {"title": "Непрерывность обратной", "text": "Для каждого конечного R>0 теорема из конспекта применяется к x² на [0,R] и даёт непрерывную обратную √y на [0,R²]. Выбирая R больше √y₀ для произвольного y₀≥0, получаем непрерывность во всех точках [0,+∞), в нуле — справа."}], "35": [{"title": "Левый предел", "text": "Для отрицательных аргументов достаточно близко к 0 функция постоянно равна −1. Поэтому предел слева равен −1."}, {"title": "Правый предел", "text": "Справа функция постоянно равна 1, поэтому предел справа равен 1."}, {"title": "Классификация", "text": "Оба односторонних предела конечны, но различны. Это разрыв первого рода типа скачка."}, {"title": "Величина скачка", "text": "Правый предел минус левый равен 1−(−1)=2."}, {"title": "Почему нельзя устранить", "text": "Изменение единственного значения f(0) не меняет ни одного одностороннего предела. Сделать их равными таким изменением нельзя."}], "36": [{"title": "Записать множество допустимых пар", "text": "При δ=1/2 берём x,y∈(0,1) с |x−y|<1/2. Нужно найти супремум |x²−y²|."}, {"title": "Получить оценку", "text": "Можно считать y≥x и положить d=y−x<1/2. Тогда y²−x²=d(2y−d)≤2d−d²≤3/4."}, {"title": "Построить приближающие пары", "text": "Положим y=1−h и x=1/2 при 0<h<1/2. Оба аргумента допустимы, расстояние 1/2−h строго меньше 1/2."}, {"title": "Проверить точность", "text": "Разность (1−h)²−1/4 стремится к 3/4 при h→0⁺. Значит, меньшая верхняя грань не подойдёт."}, {"title": "Сформулировать ответ", "text": "Модуль равен 3/4. Это супремум; исключённые граничные аргументы и строгое ограничение расстояния не мешают приблизиться к нему."}], "37": [{"title": "Чтение области", "text": "Обозначение [0,5;1] означает отрезок [1/2,1]. В нём аргумент не приближается к нулю."}, {"title": "Непрерывность композиции", "text": "Функция 1/x непрерывна на этом отрезке, а синус непрерывен на ℝ. Следовательно, sin(1/x) непрерывна на [1/2,1]."}, {"title": "Теорема Кантора", "text": "Отрезок замкнут и ограничен, поэтому непрерывность на нём влечёт равномерную непрерывность."}, {"title": "Прямая оценка", "text": "Для x,y≥1/2 имеем |sin(1/x)−sin(1/y)|≤|1/x−1/y|=|x−y|/(xy)≤4|x−y|."}, {"title": "Общий радиус", "text": "Для каждого ε>0 подходит δ=ε/4 сразу для всех пар x,y из отрезка. Это проверяет равномерную непрерывность без обращения к теореме."}]}, "exercises": {"1": [{"title": "Записать условия", "text": "Пусть X,Y непусты и ограничены сверху, a=sup X, b=sup Y конечны. По определению X+Y состоит из всех сумм x+y."}, {"title": "Доказать верхнюю оценку", "text": "Для любых x∈X,y∈Y имеем x≤a,y≤b. Складывая, получаем x+y≤a+b. Поэтому a+b — верхняя грань X+Y."}, {"title": "Поставить задачу точности", "text": "Одной верхней оценки недостаточно. Нужно для каждого ε>0 построить сумму строго больше a+b−ε."}, {"title": "Разделить погрешность", "text": "По точности sup X найдётся xε∈X с a−ε/2<xε≤a. Независимо выбираем yε∈Y с b−ε/2<yε≤b."}, {"title": "Сложить выбранные элементы", "text": "Сумма zε=xε+yε принадлежит X+Y и удовлетворяет a+b−ε<zε≤a+b."}, {"title": "Исключить меньшую грань", "text": "Если c<a+b, берём ε=a+b−c. Найденный zε>c показывает, что c не является верхней гранью."}, {"title": "Заключение", "text": "Значит, a+b — наименьшая верхняя грань, то есть sup(X+Y)=sup X+sup Y. Достижение супремумов в исходных множествах не использовалось."}], "2": [{"title": "Обозначить грани", "text": "Пусть X,Y непусты, ограничены снизу, a=inf X,b=inf Y. Для z∈X+Y пишем z=x+y."}, {"title": "Проверить нижнюю оценку", "text": "Из x≥a и y≥b следует z≥a+b. Следовательно, a+b — нижняя грань суммы."}, {"title": "Сформулировать точность", "text": "Чтобы это была наибольшая нижняя грань, достаточно для каждого ε>0 найти z∈X+Y с z<a+b+ε."}, {"title": "Выбрать элементы", "text": "По определению inf существуют xε∈X с a≤xε<a+ε/2 и yε∈Y с b≤yε<b+ε/2."}, {"title": "Сложить оценки", "text": "Для zε=xε+yε получаем a+b≤zε<a+b+ε."}, {"title": "Исключить большую грань", "text": "Если c>a+b, выбираем ε=c−a−b. Тогда zε<c, поэтому c не может быть нижней гранью X+Y."}, {"title": "Заключение", "text": "Обе части определения выполнены: inf(X+Y)=a+b. Это доказательство не требует наличия минимумов."}], "3": [{"title": "Обозначить нижнюю грань", "text": "Пусть a=inf X существует в ℝ. Множество −X состоит из чисел −x при x∈X."}, {"title": "Изменить знак неравенства", "text": "Для каждого x∈X имеем a≤x. После умножения на −1 получаем −x≤−a, то есть −a — верхняя грань −X."}, {"title": "Использовать точность inf", "text": "Для любого ε>0 найдётся xε∈X с a≤xε<a+ε."}, {"title": "Отразить выбранный элемент", "text": "Число zε=−xε принадлежит −X. Неравенства меняют направление: −a−ε<zε≤−a."}, {"title": "Проверить точность sup", "text": "Элементы −X подходят к −a снизу ближе любого ε. Значит, ни одно меньшее число не будет верхней гранью."}, {"title": "Ответ", "text": "Получаем sup(−X)=−a=−inf X. Ключевой переход — смена направления неравенств при отражении."}], "4": [{"title": "Обозначить верхнюю грань", "text": "Пусть b=sup X конечна. Тогда каждый x∈X удовлетворяет x≤b."}, {"title": "Отразить множество", "text": "Элементы −X имеют вид z=−x. Из x≤b следует z≥−b, поэтому −b — нижняя грань."}, {"title": "Приблизиться к sup", "text": "Для ε>0 существует xε∈X с b−ε<xε≤b."}, {"title": "Отразить приближение", "text": "Для zε=−xε получаем −b≤zε<−b+ε."}, {"title": "Проверить наибольшесть", "text": "Если c>−b, выбираем ε=c+b. Тогда найденный zε<c, то есть c не является нижней гранью −X."}, {"title": "Ответ", "text": "Следовательно, inf(−X)=−b=−sup X. Конечность b и непустота X обеспечивают корректность использования ε-критерия."}], "5": [{"title": "Расшифровать порядок", "text": "Условие X≤Y означает x≤y для всех x∈X и y∈Y. Оно не означает включения множеств."}, {"title": "Проверить существование граней", "text": "Здесь рассматриваются непустые множества с конечными нужными sup. В частности, можно выбрать y₀∈Y."}, {"title": "Получить верхнюю грань X", "text": "Фиксируем этот y₀. По условию все x∈X удовлетворяют x≤y₀, так что y₀ — верхняя грань X."}, {"title": "Использовать точность", "text": "Наименьшая верхняя грань не больше любой верхней грани. Поэтому sup X≤y₀."}, {"title": "Сравнить с sup Y", "text": "Так как y₀∈Y, имеем y₀≤sup Y. По транзитивности sup X≤y₀≤sup Y."}, {"title": "Заключение", "text": "Итак, sup X≤sup Y. Нельзя подменять гипотезу X≤Y условием «существует одна удачная пара x≤y»."}], "6": [{"title": "Расшифровать условие", "text": "Для любых x∈X,y∈Y выполнено x≤y. Множества непусты, нужные точные нижние грани конечны."}, {"title": "Зафиксировать элемент X", "text": "Выбираем x₀∈X. По определению нижней грани inf X≤x₀."}, {"title": "Получить общую оценку", "text": "Для каждого y∈Y условие даёт x₀≤y. Поэтому inf X≤x₀≤y для всех y∈Y."}, {"title": "Распознать нижнюю грань", "text": "Последняя оценка означает: число inf X является нижней гранью Y."}, {"title": "Использовать наибольшесть", "text": "Число inf Y — наибольшая нижняя грань Y. Следовательно, inf X≤inf Y."}, {"title": "Проверить направление", "text": "Нижняя грань меньше или равна inf, а не наоборот. Именно это направление завершает доказательство."}], "7": [{"title": "Записать разделённость", "text": "Условие X≥Y означает y≤x для всех y∈Y и x∈X. Предполагаем непустоту и конечность рассматриваемых граней."}, {"title": "Зафиксировать x", "text": "Для произвольного x∈X все y∈Y удовлетворяют y≤x. Значит, x — верхняя грань Y."}, {"title": "Использовать sup Y", "text": "Из наименьшести точной верхней грани получаем sup Y≤x."}, {"title": "Вернуть произвольность", "text": "Выбор x был произвольным, поэтому sup Y≤x для каждого x∈X."}, {"title": "Распознать нижнюю грань X", "text": "Таким образом, sup Y — нижняя грань X, а значит sup Y≤inf X."}, {"title": "Итог", "text": "Переписывая последнее неравенство, получаем inf X≥sup Y. Условие сравнивает все пары элементов, а не только какие-то отдельные."}], "8": [{"title": "Построить сечение", "text": "Пусть X непусто и ограничено снизу. Положим A={t∈ℝ: t≤x для всех x∈X}, B=ℝ\\A. В A находятся все нижние грани X."}, {"title": "Доказать непустоту частей", "text": "Из ограниченности снизу хотя бы одна нижняя грань принадлежит A. Выбрав x₀∈X, видим, что x₀+1∉A, значит B тоже непусто."}, {"title": "Проверить порядок частей", "text": "Если a∈A и b∈B, то b не нижняя грань: найдётся x∈X с x<b. Тогда a≤x<b, то есть a<b."}, {"title": "Применить полноту", "text": "Лемма о сечении даёт c с a≤c≤b для всех a∈A,b∈B."}, {"title": "Доказать c∈A", "text": "Если бы нашлось x∈X с x<c, то t=(x+c)/2 удовлетворяло бы x<t<c. Из x<t следует t∉A, значит t∈B. Но для B должно выполняться c≤t — противоречие."}, {"title": "Установить точность", "text": "Теперь c — нижняя грань X, а каждое a∈A удовлетворяет a≤c по свойству разделителя."}, {"title": "Заключение", "text": "Число c — наибольшая из всех нижних граней, то есть c=inf X. Существование доказано непосредственно через полноту, без готовой формулы с sup(−X)."}], "9": [{"title": "Понять силу гипотезы", "text": "В каждой окрестности a должны находиться бесконечно многие члены. Это допускает существование других членов очень далеко от a."}, {"title": "Построить пример", "text": "Берём a=0, x₂ₖ=0 и x₂ₖ₋₁=k. Чётные и нечётные индексы определяют все члены последовательности."}, {"title": "Проверить гипотезу", "text": "Для любого ε>0 каждый чётный член удовлетворяет |x₂ₖ−0|=0<ε. Чётных индексов бесконечно много."}, {"title": "Опровергнуть ограниченность", "text": "Для любого M>0 выбираем натуральное k>M. Тогда x₂ₖ₋₁=k>M, значит общей границы модулей нет."}, {"title": "Опровергнуть сходимость", "text": "Сходящаяся последовательность обязана быть ограниченной, а наш пример неограничен. Можно также сравнить постоянную нулевую подпоследовательность с нечётной, уходящей вверх."}, {"title": "Вывод", "text": "Из гипотезы не следуют ни сходимость, ни ограниченность. Она описывает предельную точку, а не близость всего хвоста к ней."}], "10": [{"title": "Различить свойства", "text": "Неограниченность требует сколь угодно больших по модулю отдельных членов. Она не запрещает бесконечно многим другим членам оставаться около конечного числа."}, {"title": "Задать последовательность", "text": "Пусть x₂ₖ=0, x₂ₖ₋₁=k при k≥1."}, {"title": "Проверить неограниченность", "text": "Для каждого M>0 существует нечётный член k>M. Поэтому последовательность неограниченна."}, {"title": "Проверить предельную точку", "text": "Подпоследовательность с возрастающими индексами nₖ=2k постоянно равна 0 и сходится к 0."}, {"title": "Связать с определением", "text": "Значит, 0 — конечная предельная точка исходной последовательности, хотя вся она не имеет конечного предела."}, {"title": "Ответ", "text": "Такая ситуация возможна. Не следует заменять в условии «неограниченная» на более сильное «бесконечно большая»."}], "11": [{"title": "Записать предположение", "text": "Пусть |xₙ|→∞. Допустим противное: есть подпоследовательность xₙₖ→a∈ℝ."}, {"title": "Оценить сходящуюся подпоследовательность", "text": "Для точности 1 существует K₁, после которого |xₙₖ−a|<1. По треугольнику |xₙₖ|<|a|+1."}, {"title": "Использовать бесконечную величину", "text": "Для порога M=|a|+2 существует N, после которого каждый член исходной последовательности имеет |xₙ|>|a|+2."}, {"title": "Согласовать индексы", "text": "Индексы подпоследовательности строго возрастают, поэтому nₖ→∞. Можно выбрать k>K₁ одновременно с nₖ>N."}, {"title": "Получить противоречие", "text": "Один и тот же член должен удовлетворять |xₙₖ|<|a|+1 и |xₙₖ|>|a|+2. Это невозможно."}, {"title": "Заключение", "text": "У бесконечно большой по модулю последовательности нет конечных предельных точек. Знак её членов в доказательстве не важен."}], "12": [{"title": "Проверить отсутствие ограниченности", "text": "Без дополнительной гипотезы ответ отрицательный: x₂ₖ=0,x₂ₖ₋₁=k не сходится."}, {"title": "Доказать единственность точки примера", "text": "Нулевая подпоследовательность даёт предельную точку 0. Любая подпоследовательность с бесконечно многими нечётными индексами содержит члены k, уходящие вверх, и не может сходиться к конечному числу. Поэтому других конечных предельных точек нет."}, {"title": "Сформулировать усиленный вариант", "text": "Теперь пусть исходная последовательность ограничена и имеет единственную предельную точку a. Докажем xₙ→a."}, {"title": "Отрицать сходимость", "text": "Если сходимости к a нет, существуют ε₀>0 и сколь угодно поздние индексы с |xₙ−a|≥ε₀. Последовательно выбираем из них n₁<n₂<… ."}, {"title": "Выделить новый предел", "text": "Подпоследовательность xₙₖ ограничена. По Больцано–Вейерштрассу в ней есть сходящаяся подпоследовательность xₙₖⱼ→b."}, {"title": "Сохранить отделённость", "text": "Из |xₙₖⱼ−a|≥ε₀ при переходе к пределу получаем |b−a|≥ε₀, так что b≠a."}, {"title": "Противоречие и итог", "text": "Число b — вторая предельная точка исходной последовательности, что противоречит единственности. Поэтому с ограниченностью утверждение верно, без неё — нет."}], "13": [{"title": "Уточнить корни", "text": "Пусть k — натуральное число. Для чётного k требуем xₙ≥0 и a≥0. При k=1 утверждение совпадает с xₙ→a; далее k≥2."}, {"title": "Положительный предел", "text": "При a>0 и неотрицательных xₙ обозначим uₙ=√[k](xₙ), v=√[k](a)>0. Формула разности степеней даёт xₙ−a=(uₙ−v)(uₙᵏ⁻¹+uₙᵏ⁻²v+…+vᵏ⁻¹)."}, {"title": "Оценить знаменатель", "text": "Все слагаемые суммы неотрицательны, а последнее равно vᵏ⁻¹>0. Поэтому |uₙ−v|≤|xₙ−a|/vᵏ⁻¹."}, {"title": "Выбрать номер по ε", "text": "Для ε>0 из xₙ→a выбираем N с |xₙ−a|<εvᵏ⁻¹ при n>N. Полученная оценка даёт |uₙ−v|<ε."}, {"title": "Случай a=0", "text": "Для ε>0 выбираем N с |xₙ|<εᵏ. Тогда |√[k](xₙ)|=√[k](|xₙ|)<ε; здесь для нечётного k допускаются и отрицательные xₙ."}, {"title": "Нечётный k при a>0", "text": "Если знак xₙ заранее не ограничен, из xₙ→a>0 сначала получаем xₙ>a/2>0 в хвосте и применяем уже доказанную оценку к этому хвосту."}, {"title": "Отрицательный предел", "text": "Он возможен только при нечётном k. Положим yₙ=−xₙ→−a>0. По положительному случаю √[k](yₙ)→√[k](−a), а √[k](xₙ)=−√[k](yₙ)."}, {"title": "Итог", "text": "Во всех допустимых случаях √[k](xₙ)→√[k](a). Непрерывность корня здесь доказана, а не использована как готовое обоснование самой себя."}], "14": [{"title": "Записать отрицание Коши", "text": "Достаточно найти ε₀>0 такое, что для любого N существуют m,n>N с |Hₘ−Hₙ|≥ε₀."}, {"title": "Зафиксировать ε₀", "text": "Берём ε₀=1/2. Это один и тот же порог для всех N."}, {"title": "Выбрать индексы", "text": "Для произвольного N выбираем натуральное n>N и m=2n. Тогда m тоже больше N."}, {"title": "Вычесть суммы", "text": "Общие первые n слагаемых сокращаются, поэтому H₂ₙ−Hₙ=Σ от j=n+1 до 2n величины 1/j."}, {"title": "Оценить каждое слагаемое", "text": "Для n+1≤j≤2n имеем 1/j≥1/(2n). Слагаемых ровно n, поэтому разность не меньше n/(2n)=1/2."}, {"title": "Получить нарушение", "text": "Значит, |H₂ₙ−Hₙ|≥ε₀ для сколь угодно поздних индексов. Последовательность не удовлетворяет критерию Коши и не имеет конечного предела."}, {"title": "Дополнительный вывод", "text": "Hₙ возрастает. Если бы она была ограничена сверху, монотонная теорема дала бы конечный предел. Поэтому она неограниченна сверху и Hₙ→+∞."}], "15": [{"title": "Использовать плотность", "text": "В любой проколотой окрестности произвольной точки a есть рациональные и иррациональные числа."}, {"title": "Метод Гейне: выбрать аргументы", "text": "Для каждого n выбираем рациональное qₙ≠a и иррациональное rₙ≠a с |qₙ−a|<1/n и |rₙ−a|<1/n."}, {"title": "Метод Гейне: сравнить значения", "text": "Получаем qₙ→a,rₙ→a, но D(qₙ)=1 и D(rₙ)=0. Разные пределы значений исключают общий предел в a."}, {"title": "Метод Коши: предположить предел", "text": "Допустим D(x)→A. Для ε=1/3 должен существовать δ, при котором все значения в проколотой δ-окрестности отличаются от A меньше чем на 1/3."}, {"title": "Метод Коши: построить противоречие", "text": "Выбираем там рациональную q и иррациональную r. Тогда |1−A|<1/3 и |A−0|<1/3. По треугольнику 1≤|1−A|+|A|<2/3 — невозможно."}, {"title": "Критерий Коши", "text": "Для ε₀=1/2 в любой δ-окрестности та же пара даёт |D(q)−D(r)|=1≥ε₀. Не существует радиуса, делающего все пары значений близкими."}, {"title": "Заключение", "text": "Точка a была произвольна, поэтому функция Дирихле не имеет предела ни в одной точке ℝ. Все три доказательства используют конкретное нарушение, а не только слово «разрывна»."}], "16": [{"title": "Выбрать положительные аргументы", "text": "Положим xₙ=1/(2πn), yₙ=1/((2n+1)π) при n≥1. Оба аргумента положительны и стремятся к 0."}, {"title": "Вычислить значения", "text": "cos(1/xₙ)=cos(2πn)=1; cos(1/yₙ)=cos((2n+1)π)=−1."}, {"title": "Исключить правый предел", "text": "По Гейне два разных предела значений 1 и −1 исключают существование предела справа."}, {"title": "Перейти на левую сторону", "text": "Аргументы −xₙ и −yₙ стремятся к 0 слева. Косинус чётен, поэтому значения по-прежнему 1 и −1. Левого предела тоже нет."}, {"title": "Обоснование по Коши", "text": "Если бы односторонний предел был A, при ε=1/2 значения 1 и −1 должны были бы одновременно находиться ближе 1/2 к A. Тогда 2≤|1−A|+|A+1|<1, что невозможно."}, {"title": "Критерий Коши", "text": "Выбираем ε₀=1. В любой достаточно малой односторонней окрестности есть указанные точки с разностью значений 2≥1."}, {"title": "Вывод", "text": "Оба односторонних предела отсутствуют из-за сохраняющейся амплитуды колебаний, а не потому, что сама функция где-то не ограничена."}], "17": [{"title": "Степень: разложить разность", "text": "Для натурального p≥1 имеем xᵖ−aᵖ=(x−a)(xᵖ⁻¹+xᵖ⁻²a+…+aᵖ⁻¹). Если |x−a|<1, то |x|≤|a|+1 и сумма модулей не больше p(|a|+1)ᵖ⁻¹."}, {"title": "Степень: выбрать δ", "text": "Для ε>0 берём δ=min(1,ε/[p(|a|+1)ᵖ⁻¹]). Тогда |x−a|<δ влечёт |xᵖ−aᵖ|<ε. Постоянная степень p=0 непрерывна отдельно как константа."}, {"title": "Корень при a>0", "text": "Для u=√[p](x),v=√[p](a)>0 на неотрицательных аргументах формула разности степеней даёт |u−v|≤|x−a|/vᵖ⁻¹. Подходит δ=εvᵖ⁻¹ в области корня."}, {"title": "Нуль и отрицательные аргументы корня", "text": "При a=0 берём δ=εᵖ. Для нечётного p и a<0 заменяем x,a на −x,−a; при a>0 и нечётном p дополнительно ограничиваем δ≤a/2, чтобы остаться на положительных аргументах."}, {"title": "Синус: получить оценку", "text": "По формуле разности и неравенству |sin t|≤|t| имеем |sin x−sin a|=2|sin((x−a)/2)cos((x+a)/2)|≤|x−a|. Подходит δ=ε."}, {"title": "Косинус: получить оценку", "text": "Аналогично |cos x−cos a|=2|sin((x+a)/2)sin((x−a)/2)|≤|x−a|. Снова выбираем δ=ε."}, {"title": "Обратная функция: отделить знаменатель", "text": "Для f(x)=1/x и a≠0 требуем |x−a|<|a|/2. Тогда |x|≥|a|−|x−a|>|a|/2."}, {"title": "Обратная функция: завершить оценку", "text": "Имеем |1/x−1/a|=|x−a|/(|x||a|)≤2|x−a|/a². Выбор δ=min(|a|/2,εa²/2) делает разность меньше ε."}, {"title": "Проверка метода", "text": "Для каждой функции явно назван положительный δ и доказана требуемая оценка. Слова «элементарная функция» сами по себе не заменяют доказательства по определению."}], "18": [{"title": "Расшифровать символы", "text": "Пусть α(x)=o(xⁿ), β(x)=o(xᵐ) при x→0. На проколотой области пишем α=xⁿu, β=xᵐv, где u→0 и v→0."}, {"title": "Выбрать общий масштаб", "text": "Положим r=min(n,m). Тогда n−r≥0 и m−r≥0."}, {"title": "Разделить на нужную степень", "text": "(α±β)/xʳ=xⁿ⁻ʳu±xᵐ⁻ʳv при x≠0."}, {"title": "Ограничить степенные множители", "text": "При 0<|x|<1 обе степени с неотрицательными показателями имеют модуль не больше 1."}, {"title": "Получить стремление к нулю", "text": "Поэтому |(α±β)/xʳ|≤|u|+|v|→0. Для ε>0 достаточно одновременно |u|<ε/2 и |v|<ε/2."}, {"title": "Вернуться к обозначению", "text": "Предел отношения равен нулю, значит α±β=o(xʳ)=o(x^min(n,m)). Знак минус не меняет доказательство благодаря модулю."}], "19": [{"title": "Представить малые", "text": "Из α=o(xⁿ), β=o(xᵐ) получаем α=xⁿu и β=xᵐv, где u,v→0 на рассматриваемой проколотой области."}, {"title": "Перемножить равенства", "text": "αβ=xⁿ⁺ᵐuv. Это точное равенство, а не правило, принятое без проверки."}, {"title": "Разделить на масштаб", "text": "При x≠0 отношение αβ/xⁿ⁺ᵐ равно uv."}, {"title": "Обосновать предел произведения", "text": "Так как v→0, в некоторой окрестности |v|≤1. Тогда |uv|≤|u|→0. Можно также применить теорему о произведении пределов."}, {"title": "Проверить по ε", "text": "Выбираем окрестность, где одновременно |v|≤1 и |u|<ε. Тогда |αβ/xⁿ⁺ᵐ|<ε."}, {"title": "Итог", "text": "Именно это означает αβ=o(xⁿ⁺ᵐ). Показатели складываются, поскольку перемножаются степенные масштабы."}], "20": [{"title": "Назвать вложенные величины", "text": "Пусть α=o(xᵐ), β=o(αⁿ), n — положительное целое. На области определения отношений положим α=xᵐu, β=αⁿv, где u,v→0."}, {"title": "Подставить внутреннее представление", "text": "Получаем β=(xᵐu)ⁿv=xᵐⁿuⁿv."}, {"title": "Выделить требуемое отношение", "text": "При x≠0 имеем β/xᵐⁿ=uⁿv."}, {"title": "Обосновать малость", "text": "Из u→0 следует uⁿ→0. Кроме того, v ограничена в некоторой окрестности, например |v|≤1. Поэтому |uⁿv|≤|u|ⁿ→0."}, {"title": "Проверить ε-выбор", "text": "Для заданного ε>0 достаточно добиться |v|≤1 и |u|<ε^(1/n). Тогда |β/xᵐⁿ|<ε."}, {"title": "Уточнить нули", "text": "Если определение o через отношения исключает нули α, доказательство относится к этой области. Если используются представления β=αⁿv с продолжением v в нулях, равенство β=xᵐⁿuⁿv охватывает и их."}, {"title": "Вывод", "text": "Получаем β=o(xᵐⁿ). Условие n>0 нужно, чтобы из u→0 следовало uⁿ→0."}], "21": [{"title": "Указать область отношения", "text": "Рассматриваем аргументы с α(x)≠0; исходная дробь sin α(x)/α(x) на нулях α не определена. Предельная точка должна быть точкой сгущения этой области."}, {"title": "Взять точность внешнего предела", "text": "По первому замечательному пределу для каждого ε>0 существует η>0: из 0<|t|<η следует |sin t/t−1|<ε."}, {"title": "Использовать малость α", "text": "Так как α(x)→0 при x→x₀, существует δ>0, при котором допустимые x с 0<|x−x₀|<δ дают |α(x)|<η."}, {"title": "Соединить условия", "text": "На области исходной дроби α(x)≠0, значит 0<|α(x)|<η. Можно подставить t=α(x) в уже полученную оценку."}, {"title": "Получить требуемое неравенство", "text": "Имеем |sin α(x)/α(x)−1|<ε для всех таких x. Это определение предела 1."}, {"title": "Обработать нули при продолжении", "text": "Если хотим определять выражение и там, где α=0, задаём h(0)=1 для h(t)=sin t/t. Тогда композиция h(α(x)) имеет тот же предел на всей области."}], "22": [{"title": "Проверить степень", "text": "Вещественное выражение (1+α)^(1/α) требует α≠0 и 1+α>0. Из α→0 следует |α|<1/2 в достаточно малой окрестности, поэтому положительность основания обеспечена."}, {"title": "Использовать второй замечательный предел", "text": "Для ε>0 найдётся η>0, η<1/2, такое, что при 0<|t|<η выполняется |(1+t)^(1/t)−e|<ε."}, {"title": "Подобрать окрестность аргумента", "text": "Из α(x)→0 выбираем δ, для которого 0<|x−x₀|<δ влечёт |α(x)|<η."}, {"title": "Проверить все ограничения", "text": "На области исходного выражения α(x)≠0. В выбранной окрестности также 1+α(x)>1/2, поэтому подстановка t=α(x) допустима."}, {"title": "Получить оценку", "text": "Неравенство внешнего предела превращается в |(1+α(x))^(1/α(x))−e|<ε. Следовательно, предел равен e."}, {"title": "Уточнить нули α", "text": "В нулях исходная запись не определена. Можно либо брать предел по её области, либо отдельно продолжить внешнюю функцию значением e при t=0."}], "23": [{"title": "Рассмотреть неубывание", "text": "Пусть xₙ₊₁≥xₙ. Тогда все члены не меньше x₁, так что последовательность уже ограничена снизу."}, {"title": "Установить сторону неограниченности", "text": "Если она неограниченна, то в этом случае не может быть ограниченной сверху: две грани сделали бы её ограниченной по модулю."}, {"title": "Выбрать порог", "text": "Для любого M>0 по неограниченности сверху найдётся N с x_N>M."}, {"title": "Распространить на хвост", "text": "При n≥N неубывание даёт xₙ≥x_N>M. Это определение xₙ→+∞."}, {"title": "Рассмотреть невозрастание", "text": "Если xₙ₊₁≤xₙ, последовательность ограничена сверху x₁. Неограниченность заставляет её быть неограниченной снизу."}, {"title": "Получить отрицательную бесконечность", "text": "Для M>0 выбираем N с x_N<−M; тогда n≥N даёт xₙ≤x_N<−M. Значит, xₙ→−∞."}, {"title": "Общий вывод", "text": "В обоих случаях |xₙ|→∞. Монотонность нужна именно для переноса одной большой величины на весь последующий хвост."}], "24": [{"title": "Доказать неограниченность каждого хвоста", "text": "Если после некоторого N модули были бы ограничены M, то максимум M и модулей первых N членов ограничил бы всю последовательность. Это противоречит условию."}, {"title": "Начать выбор", "text": "В первом хвосте найдём индекс n₁ с |xₙ₁|>1."}, {"title": "Выполнить шаг индукции", "text": "Когда nₖ уже выбран, хвост после nₖ остаётся неограниченным. Выбираем в нём nₖ₊₁>nₖ с |xₙₖ₊₁|>k+1."}, {"title": "Проверить подпоследовательность", "text": "Индексы строго возрастают, поэтому полученные члены действительно образуют подпоследовательность, а не произвольную перестановку."}, {"title": "Проверить бесконечную величину", "text": "Для каждого M>0 берём натуральное K>M. При k≥K имеем |xₙₖ|>k≥K>M."}, {"title": "Вывод", "text": "Это определение |xₙₖ|→∞. Знак может чередоваться; доказана бесконечная величина по модулю, а не обязательно предел +∞."}], "25": [{"title": "Записать определение", "text": "При δ>0 модуль ω_f(δ;E) — sup |f(x)−f(y)| по x,y∈E со строгим условием |x−y|<δ, как в вопросе 36 нового конспекта."}, {"title": "Интервал (0,1): верхняя граница", "text": "Значения синуса лежат в [−1,1], поэтому любая разность по модулю не превышает 2."}, {"title": "Интервал (0,1): достижение разности", "text": "Берём xₙ=1/(π/2+2πn), yₙ=1/(3π/2+2πn). При больших n обе точки лежат в (0,1), расстояние между ними стремится к 0, а значения равны 1 и −1. При каждом δ>0 найдётся пара с расстоянием строго меньше δ с разностью 2."}, {"title": "Интервал (0,1): вывод", "text": "Итак, ω(δ)=2 для каждого δ>0. Модуль не стремится к 0, следовательно, равномерной непрерывности здесь нет."}, {"title": "Отрезок [1/2,1]: быстрая оценка", "text": "Имеем |sin(1/x)−sin(1/y)|≤|1/x−1/y|=|x−y|/(xy)≤4|x−y|. Поэтому ω(δ)≤4δ→0. Это доказывает равномерную непрерывность, но ещё не точный модуль."}, {"title": "Расположение вершины", "text": "Положим c=2/π. На [1/2,c] аргумент 1/x убывает от 2 до π/2, и sin(1/x) возрастает; на [c,1] функция убывает от 1 до sin 1."}, {"title": "Левая ветвь: увеличить расстояние", "text": "Для пары u,u+d на [1/2,c] разность возрастает с d. При строгом d<δ граничное расстояние δ используется только в предельном переходе; его значение даёт супремум разностей."}, {"title": "Левая ветвь: сдвинуть к краю", "text": "Для фиксированного d разность равна 2[−cos((1/u+1/(u+d))/2)]sin(d/[2u(u+d)]). На левой ветви оба множителя неотрицательны и не возрастают при росте u. Значит, лучшая пара начинается в u=1/2."}, {"title": "Записать левый вклад", "text": "Получаем A(δ)=sin(1/[1/2+min(δ,c−1/2)] )−sin 2. Если пары уже достигают вершины c, дальнейшее увеличение δ левый вклад не меняет. Если min(δ,c−1/2)=δ, значение получается при d↑δ, а не обязательным достижением на допустимой паре."}, {"title": "Правая ветвь", "text": "При 0<δ<1−c получаем B(δ)=max по c≤u≤1−δ выражения sin(1/u)−sin(1/(u+δ)). Для модуля со строгим расстоянием это значение супремума: пары расстояния δ приближаются парами с d<δ; непрерывность сохраняет предельную разность."}, {"title": "Насыщение правой ветви", "text": "При δ>1−c допустима пара c,1. При δ=1−c её значение приближается допустимыми парами. В обоих случаях B(δ)=1−sin 1 — полный разброс правой ветви как супремум."}, {"title": "Пары через вершину", "text": "Если x≤c≤y, то |f(x)−f(y)| не больше max(1−f(x),1−f(y)). Соответствующая пара x,c или c,y имеет не большее расстояние. Значит, такие пары не улучшают максимум двух ветвей."}, {"title": "Собрать точный ответ", "text": "На [1/2,1] имеем ω(δ)=max(A(δ),B(δ)). Поскольку sin 2>sin 1, для δ≥1−2/π весь модуль равен 1−sin 1. Формула через максимум является точной; оценку 4δ нельзя выдавать за равенство."}], "26": [{"title": "Начать с (0,1)", "text": "Для δ>0 рассматриваются пары со строгим |x−y|<δ. На (0,1) можно считать 0<x≤y<1, положить d=y−x<δ и записать y²−x²=d(2y−d)."}, {"title": "Оценить сверху", "text": "При 0<δ≤1 имеем 0≤d<δ и y<1. Поэтому d(2y−d)≤2d−d²≤2δ−δ²; функция 2d−d² возрастает на [0,1]."}, {"title": "Доказать точность", "text": "При 0<δ<1 берём y=1−h, x=1−δ с h→0⁺ и h<δ. Обе точки принадлежат (0,1), расстояние δ−h строго меньше δ, а разность квадратов стремится к 2δ−δ²."}, {"title": "Большие расстояния", "text": "При δ≥1 разность квадратов на (0,1) меньше 1. Пары x→0⁺,y→1⁻ имеют расстояние меньше 1≤δ и приближают разность к 1. Поэтому супремум равен 1."}, {"title": "Перейти к [−2,1]", "text": "На отрицательной ветви пишем x=−u,y=−v, где 0≤v≤u≤2. При d=u−v разность квадратов равна d(2u−d)≤4d−d²."}, {"title": "Максимум отрицательной ветви", "text": "При 0<δ≤2 разность не больше 4δ−δ². Пары −2,−2+d при d↑δ и d<δ допустимы, а их разности 4d−d² стремятся к этой грани. Это доказывает точность супремума без включения расстояния δ."}, {"title": "Проверить положительную ветвь", "text": "Для 0≤x,y≤1 при δ≤1 разность не больше 2δ−δ²≤4δ−δ². При 1≤δ≤2 она не больше 1, тогда как 4δ−δ²≥3."}, {"title": "Проверить разные знаки", "text": "Если x≤0≤y и больший квадрат принадлежит x, заменяем пару на x,0. Если больший квадрат принадлежит y — на 0,y. Разность увеличивается или сохраняется, а расстояние не увеличивается. Значит, достаточно уже рассмотренных ветвей."}, {"title": "Проверить δ≥2", "text": "При δ>2 пара −2,0 допустима и даёт разность 4. При δ=2 берём −2 и −h, h→0⁺: расстояние 2−h<2, а разность 4−h²→4. Значит, при δ≥2 супремум равен 4."}, {"title": "Собрать формулы", "text": "На (0,1): ω=2δ−δ² при 0<δ≤1 и ω=1 при δ≥1. На [−2,1]: ω=4δ−δ² при 0<δ≤2 и ω=4 при δ≥2. Оба модуля стремятся к 0 при δ→+0, поэтому обе функции равномерно непрерывны."}]}};
COURSE.forEach(t=>{t.solution=DETAILED_SOLUTIONS.practice[t.id].map(s=>s.title+". "+s.text)});
